INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-exam-linear-algebra-set-20-s0-0', 'exam-linear-algebra-set-20', 'exam-linear-algebra-set-20-sec-0', 0, '设A,B为同阶可逆方阵，则下列', '设 A, B 为同阶可逆方阵，则下列等式中错误的是（）', '["$|AB|=|A||B|$","$(AB)^{-1}=B^{-1}A^{-1}$","$(A+B)^{-1}=A^{-1}+B^{-1}$","$(AB)^{T}=B^{T}A^{T}$"]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 2, '[]'::jsonb, '长理线代期末试卷汇总-第20套', 0) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-exam-linear-algebra-set-20-s0-1', 'exam-linear-algebra-set-20', 'exam-linear-algebra-set-20-sec-0', 0, '已知向量组中线性相关，那么', '已知向量组 $A: \\alpha_{1}, \\alpha_{2}, \\alpha_{3}, \\alpha_{4}$ 中 $\\alpha_{2}, \\alpha_{3}, \\alpha_{4}$ 线性相关，那么（）', '["$\\\\alpha_{1}, \\\\alpha_{2}, \\\\alpha_{3}, \\\\alpha_{4}$ 线性无关","$\\\\alpha_{1}, \\\\alpha_{2}, \\\\alpha_{3}, \\\\alpha_{4}$ 线性相关","$\\\\alpha_{1}$ 可由 $\\\\alpha_{2}, \\\\alpha_{3}, \\\\alpha_{4}$ 线性表示","$\\\\alpha_{3}, \\\\alpha_{4}$ 线性无关"]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 2, '[]'::jsonb, '长理线代期末试卷汇总-第20套', 1) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
